<script lang="ts">
	import { fetchNui } from "../utils/fetchNui";
	import { NUI_EVENTS } from "../constants/nuiEvents";
	import { globalNotifications } from "../services/notificationService.svelte";

	export interface OfficerProfileOfficer { citizenid?: string; firstName: string; lastName: string; callsign: string; badgeNumber: string; rank: string; department?: string; certifications: string[]; }
	let { officer, currentCitizenId, onclose, onmanage }: { officer: OfficerProfileOfficer; currentCitizenId?: string; onclose: () => void; onmanage?: () => void } = $props();
	let loading = $state(true); let saving = $state(false); let picture = $state(""); let phone = $state(""); let email = $state("");
	let certifications = $state<string[]>(officer.certifications || []);
	let certificationColors = $state<Record<string, string>>({});
	let canEditProfile = $state(false);
	let editingProfile = $state(false);
	let reports = $state<Array<{ id: number; title: string; type: string; datecreated: string }>>([]);
	let cases = $state<Array<{ id: number; case_number: string; title: string; status: string; updated_at: string }>>([]);
	type StatisticPeriod = "last30Days" | "allTime";
	type Statistics = { reports: number; arrests: number; citations: number; fines: number; jailTime: number; };
	let stats = $state<Record<StatisticPeriod, Statistics>>({ last30Days: { reports: 0, arrests: 0, citations: 0, fines: 0, jailTime: 0 }, allTime: { reports: 0, arrests: 0, citations: 0, fines: 0, jailTime: 0 } });
	let statisticPeriod = $state<StatisticPeriod>("last30Days");
	let currentStats = $derived(stats[statisticPeriod]);
	let isOwner = $derived(!!officer.citizenid && officer.citizenid === currentCitizenId);

	async function load() { loading = true; try { const [response, tags] = await Promise.all([fetchNui<any>(NUI_EVENTS.ROSTER.GET_OFFICER_PROFILE, { citizenid: officer.citizenid }), fetchNui<Array<{ name: string; color: string }>>(NUI_EVENTS.ROSTER.GET_OFFICER_TAGS, {}, [])]); if (!response?.success) throw new Error(response?.message); const data = response.data || {}; picture = data.picture || ""; phone = data.phone || ""; email = data.email || ""; canEditProfile = !!data.canEdit; certifications = data.certifications || officer.certifications || []; certificationColors = Object.fromEntries((tags || []).map(tag => [tag.name, tag.color])); reports = data.reports || []; cases = data.cases || []; stats = data.stats || stats; } catch (error) { globalNotifications.error(error instanceof Error ? error.message : "Failed to load officer profile"); } finally { loading = false; } }
	async function save() { saving = true; try { const response = await fetchNui<any>(NUI_EVENTS.ROSTER.UPDATE_MY_OFFICER_PROFILE, { picture, phone, email }); if (!response?.success) throw new Error(response?.message); globalNotifications.success(response.message || "Profile updated"); } catch (error) { globalNotifications.error(error instanceof Error ? error.message : "Failed to update profile"); } finally { saving = false; } }
	function formatDate(value: string) { return value ? new Date(value).toLocaleDateString() : "-"; }
	function money(value: number) { return new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", maximumFractionDigits: 0 }).format(value || 0); }
	$effect(() => { load(); });
</script>

<div class="profile-view">
	<div class="profile-topbar"><button class="back-btn" onclick={onclose}><span class="material-icons">arrow_back</span> Back</button><div class="profile-identity"><span class="profile-name">{officer.firstName} {officer.lastName}</span><span class="profile-cid">{officer.rank} · {officer.department || "Police Department"}</span></div>{#if canEditProfile}<button class="manage-btn" onclick={() => editingProfile = !editingProfile}>{editingProfile ? "Close editor" : "Edit my profile"}</button>{/if}{#if onmanage}<button class="manage-btn" onclick={onmanage}>Manage officer</button>{/if}</div>
	{#if loading}<div class="empty-msg">Loading officer profile...</div>
	{:else}
		<div class="statistics-header"><span>Performance Statistics</span><div class="period-toggle"><button class:active={statisticPeriod === "last30Days"} onclick={() => statisticPeriod = "last30Days"}>Last 30 Days</button><button class:active={statisticPeriod === "allTime"} onclick={() => statisticPeriod = "allTime"}>All Time</button></div></div>
		<div class="pstats-row"><div class="pstat"><span class="pstat-val">{currentStats.reports}</span><span class="pstat-lbl">Reports Filed</span></div><div class="pstat"><span class="pstat-val">{currentStats.arrests}</span><span class="pstat-lbl">Arrests</span></div><div class="pstat"><span class="pstat-val">{currentStats.reports}</span><span class="pstat-lbl">Reports</span></div><div class="pstat"><span class="pstat-val">{money(currentStats.fines)}</span><span class="pstat-lbl">Fines Issued</span></div><div class="pstat"><span class="pstat-val">{currentStats.jailTime}</span><span class="pstat-lbl">Months Issued</span></div></div>
		<div class="profile-body"><aside class="profile-sidebar"><div class="panel"><div class="profile-img">{#if picture}<img src={picture} alt="Officer profile" />{:else}<div class="no-photo-placeholder"><span class="material-icons">account_circle</span><span>No Photo</span></div>{/if}</div></div><div class="panel detail-panel"><div class="detail-row"><span>Callsign</span><strong>{officer.callsign || "-"}</strong></div><div class="detail-row"><span>Badge Number</span><strong>{officer.badgeNumber || "-"}</strong></div><div class="detail-row"><span>Department</span><strong>{officer.department || "-"}</strong></div><div class="detail-row"><span>Phone</span><strong>{phone || "Not provided"}</strong></div><div class="detail-row"><span>Email</span><strong>{email || "Not provided"}</strong></div></div>{#if canEditProfile && editingProfile}<div class="panel edit-panel"><div class="panel-title">Edit My Profile</div><label>Photo URL<input bind:value={picture} placeholder="https://..." /></label><label>Phone<input bind:value={phone} placeholder="Phone number" /></label><label>Email<input bind:value={email} type="email" placeholder="name@department.gov" /></label><button class="save-btn" onclick={save} disabled={saving}>{saving ? "Saving..." : "Save Changes"}</button></div>{/if}</aside>
			<main class="profile-main"><div class="sections-grid"><div class="panel wide-panel"><div class="panel-title">Certifications <span>{certifications.length}</span></div><div class="tags">{#each certifications as certification}<span style="background: {certificationColors[certification] || '#6b7280'}14; border-color: {certificationColors[certification] || '#6b7280'}40; color: {certificationColors[certification] || '#6b7280'}">{certification}</span>{:else}<em>No certifications recorded</em>{/each}</div></div><div class="panel"><div class="panel-title">Last 10 Reports <span>{reports.length}</span></div><div class="section-list">{#each reports as report}<div class="sitem"><div><strong>{report.title || "Untitled report"}</strong><small>{report.type || "Report"} · {formatDate(report.datecreated)}</small></div></div>{:else}<div class="empty-msg">No reports filed</div>{/each}</div></div><div class="panel"><div class="panel-title">Associated Cases <span>{cases.length}</span></div><div class="section-list">{#each cases as caseRecord}<div class="sitem"><div><strong>{caseRecord.case_number || `Case #${caseRecord.id}`}</strong><small>{caseRecord.title}</small></div><i>{caseRecord.status}</i></div>{:else}<div class="empty-msg">No cases associated</div>{/each}</div></div></div></main></div>
	{/if}
</div>

<style>
	.profile-view{height:100%;display:flex;flex-direction:column;overflow:hidden;background:var(--card-dark-bg);color:rgba(255,255,255,.8)}.profile-topbar{height:48px;display:flex;align-items:center;gap:14px;padding:0 20px;border-bottom:1px solid rgba(255,255,255,.06);flex-shrink:0}.back-btn{display:flex;gap:5px;align-items:center;border:0;background:transparent;color:rgba(255,255,255,.5);font-size:11px;cursor:pointer}.back-btn:hover{color:rgba(255,255,255,.85)}.back-btn .material-icons{font-size:15px}.profile-identity{display:flex;gap:10px;align-items:baseline;flex:1}.profile-name{font-size:14px;font-weight:600;color:rgba(255,255,255,.9)}.profile-cid{font-size:11px;color:rgba(255,255,255,.3)}.manage-btn,.save-btn{border:1px solid rgba(var(--accent-rgb),.25);border-radius:3px;background:rgba(var(--accent-rgb),.14);color:rgba(var(--accent-text-rgb),.9);padding:5px 10px;font-size:10px;cursor:pointer}.statistics-header{height:34px;padding:0 18px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(255,255,255,.06);font-size:10px;font-weight:600;text-transform:uppercase;letter-spacing:.4px;color:rgba(255,255,255,.5)}.period-toggle{display:flex;border:1px solid rgba(255,255,255,.08);border-radius:3px;overflow:hidden}.period-toggle button{border:0;border-right:1px solid rgba(255,255,255,.08);background:transparent;color:rgba(255,255,255,.35);padding:4px 8px;font-size:9px;cursor:pointer}.period-toggle button:last-child{border-right:0}.period-toggle button.active{background:rgba(var(--accent-rgb),.14);color:rgba(var(--accent-text-rgb),.9)}.pstats-row{display:flex;min-height:58px;border-bottom:1px solid rgba(255,255,255,.06);overflow-x:auto}.pstat{min-width:104px;padding:10px 18px;border-right:1px solid rgba(255,255,255,.06);display:flex;flex-direction:column;justify-content:center;gap:2px}.pstat-val{font-size:16px;font-weight:600;color:rgba(255,255,255,.88)}.pstat-lbl,.detail-row span,.edit-panel label{font-size:9px;color:rgba(255,255,255,.3);text-transform:uppercase;letter-spacing:.4px}.profile-body{display:grid;grid-template-columns:240px 1fr;flex:1;min-height:0;overflow:hidden}.profile-sidebar{padding:12px;border-right:1px solid rgba(255,255,255,.06);overflow-y:auto}.profile-main{padding:12px;overflow-y:auto}.panel{border:1px solid rgba(255,255,255,.06);background:rgba(255,255,255,.015);margin-bottom:10px}.profile-img{height:150px;display:flex;align-items:center;justify-content:center;background:rgba(255,255,255,.025);overflow:hidden}.profile-img img{width:100%;height:100%;object-fit:cover}.no-photo-placeholder{display:flex;flex-direction:column;align-items:center;gap:5px;color:rgba(255,255,255,.18);font-size:10px}.no-photo-placeholder .material-icons{font-size:42px}.detail-row{display:flex;flex-direction:column;gap:4px;padding:9px 10px;border-bottom:1px solid rgba(255,255,255,.05)}.detail-row:last-child{border-bottom:0}.detail-row strong{font:11px monospace;color:rgba(255,255,255,.72);overflow-wrap:anywhere}.panel-title{display:flex;align-items:center;gap:6px;min-height:30px;padding:0 10px;border-bottom:1px solid rgba(255,255,255,.06);font-size:10px;font-weight:600;text-transform:uppercase;letter-spacing:.4px;color:rgba(255,255,255,.65)}.panel-title span{border-radius:8px;background:rgba(255,255,255,.06);padding:2px 6px;font-size:9px;color:rgba(255,255,255,.45)}.edit-panel{display:grid;gap:8px;padding:10px}.edit-panel .panel-title{margin:-10px -10px 2px}.edit-panel label{display:grid;gap:4px}.edit-panel input{min-width:0;border:1px solid rgba(255,255,255,.09);border-radius:2px;padding:6px 7px;background:rgba(0,0,0,.13);color:rgba(255,255,255,.78);font-size:11px}.save-btn{justify-self:start}.sections-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.sections-grid .panel{margin:0}.wide-panel{grid-column:1/-1}.tags{display:flex;gap:5px;flex-wrap:wrap;padding:10px}.tags span{border:1px solid rgba(var(--accent-rgb),.2);border-radius:3px;background:rgba(var(--accent-rgb),.08);padding:2px 6px;color:rgba(var(--accent-text-rgb),.75);font-size:10px}.tags em,.empty-msg{padding:12px 10px;color:rgba(255,255,255,.25);font-size:10px;font-style:normal}.sitem{display:flex;justify-content:space-between;gap:8px;min-height:42px;padding:7px 10px;border-bottom:1px solid rgba(255,255,255,.05)}.sitem div{display:flex;flex-direction:column;gap:3px;min-width:0}.sitem strong{font-size:11px;font-weight:500;color:rgba(255,255,255,.72);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.sitem small{font-size:9px;color:rgba(255,255,255,.28)}.sitem i{font-size:9px;font-style:normal;text-transform:capitalize;color:rgba(var(--accent-text-rgb),.65)}@media(max-width:700px){.profile-body{grid-template-columns:1fr;overflow:auto}.profile-sidebar{border-right:0;border-bottom:1px solid rgba(255,255,255,.06);overflow:visible}.profile-main{overflow:visible}.sections-grid{grid-template-columns:1fr}.wide-panel{grid-column:auto}}
</style>
